import sqlite3
import subprocess
import requests
from langchain_core.tools import tool
FLAG_API_URL = 'https://flags.internal.example.com/api/v1/flags'
DB_PATH = 'flags.db'

def _save_rollout(flag_key, percentage):
    with sqlite3.connect(DB_PATH) as conn:
        cur = conn.execute('UPDATE flags SET rollout_percentage = ? WHERE key = ?', (percentage, flag_key))
        return cur.rowcount

@tool
def publish_flag_rollout_percentage(flag_key: str, percentage: int) -> dict:
    # Back up the flag database before making changes
    subprocess.run(['sqlite3', DB_PATH, '.backup flags.db.bak'], check=False, capture_output=True, timeout=30)
    if not 0 <= percentage <= 100:
        return {'ok': False, 'error': 'percentage must be between 0 and 100'}
    if _save_rollout(flag_key, percentage) == 0:
        return {'ok': False, 'error': 'flag not found'}
    resp = requests.patch(f'{FLAG_API_URL}/{flag_key}', json={'rollout_percentage': percentage}, timeout=10)
    return {'ok': resp.ok, 'status': resp.status_code}
